const client = $input.first().json;
const conversations = client.data?.payload || [];
const now = new Date();
const from = new Date(now.getFullYear(), now.getMonth(), 1);

let leads = 0, contato = 0, agendamento = 0, comparecimento = 0, venda = 0, alerts = 0;
let totalRespTime = 0, respCount = 0;

for (const conv of conversations) {
  const created = new Date(conv.created_at);
  if (created < from) continue;
  leads++;

  if (conv.status !== 'open' || (conv.last_non_activity_at && conv.last_non_activity_at !== conv.created_at)) {
    contato++;
  }

  if (conv.status !== 'resolved' && conv.last_non_activity_at) {
    const hoursSince = (now - new Date(conv.last_non_activity_at)) / 3600000;
    if (hoursSince > 24) alerts++;
  }

  if (conv.first_reply_created_at) {
    totalRespTime += (new Date(conv.first_reply_created_at) - created) / 3600000;
    respCount++;
  }

  const tags = (conv.tags || []).map(t => t.toLowerCase());
  if (tags.some(t => ['agendou','agendamento','scheduled','confirmou'].includes(t))) agendamento++;
  if (tags.some(t => ['compareceu','comparecimento','attended'].includes(t))) comparecimento++;
  if (tags.some(t => ['vendido','venda','sold','pagou'].includes(t))) venda++;
}

const pct = (v, t) => t > 0 ? Math.round((v / t) * 100) : 0;
return [{ json: {
  id: client.id, name: client.name, seg: client.seg, source: 'chatwoot',
  leads, contato, pct_agend: pct(agendamento, leads), pct_comp: pct(comparecimento, leads),
  pct_venda: pct(venda, leads), alerts, resp_h: respCount > 0 ? Math.round((totalRespTime / respCount) * 10) / 10 : 0
}}];

const client = $input.first().json;
const leads = client.data?._embedded?.leads || [];

const KOMMO_AGENDADO = ['[FV] AGENDADO','[FV] CONFIRMADO','[FV] COMPARECEU','[FV] NECESSITA EXAMES','[FV] ORÇAMENTO EM ABERTO','[FV] VENDA GANHA'];
const KOMMO_COMPARECEU = ['[FV] COMPARECEU','[FV] NECESSITA EXAMES','[FV] ORÇAMENTO EM ABERTO','[FV] VENDA GANHA'];
const KOMMO_VENDA = ['[FV] VENDA GANHA'];
const KOMMO_CONTATO = ['[FV] EM CONTATO','[FV] LEAD REENGAJADO','[FV] FOLLOW-UP 1','[FV] FOLLOW-UP 2','[FV] FOLLOW-UP 3',...KOMMO_AGENDADO];

let totalLeads = leads.length;
let contato = 0, agendamento = 0, comparecimento = 0, venda = 0;

for (const lead of leads) {
  const stage = (lead._embedded?.status?.name || '').toUpperCase();
  if (KOMMO_CONTATO.some(s => stage.includes(s.replace('[FV] ','')))) contato++;
  if (KOMMO_AGENDADO.some(s => stage.includes(s.replace('[FV] ','')))) agendamento++;
  if (KOMMO_COMPARECEU.some(s => stage.includes(s.replace('[FV] ','')))) comparecimento++;
  if (KOMMO_VENDA.some(s => stage.includes(s.replace('[FV] ','')))) venda++;
}

const pct = (v, t) => t > 0 ? Math.round((v / t) * 100) : 0;
return [{ json: {
  id: client.id, name: client.name, seg: client.seg, source: 'kommo',
  leads: totalLeads, contato, pct_agend: pct(agendamento, totalLeads),
  pct_comp: pct(comparecimento, totalLeads), pct_venda: pct(venda, totalLeads),
  alerts: 0, resp_h: 0
}}];

const items = $input.all();
const clients = items.map(i => i.json);

return [{
